Plan: copy the workbook, read the customer flags in B1:F1, the customer names in B3:F3, and the target input from B12 (defaulting to 0). Then write the matching customer names, in column order, into A13:A14 as plain values.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def clean_value(x):
    if x is None:
        return None
    if isinstance(x, str):
        s = x.strip()
        try:
            return int(s)
        except ValueError:
            try:
                return float(s)
            except ValueError:
                return s
    return x

def same_value(a, b):
    if (
        isinstance(a, (int, float))
        and isinstance(b, (int, float))
        and not isinstance(a, bool)
        and not isinstance(b, bool)
    ):
        return abs(a - b) < 1e-9
    return a == b

target = clean_value(vws.cell(row=12, column=2).value)
if target is None:
    target = 0

selected = []
for col in range(2, 7):  # B through F
    flag = clean_value(vws.cell(row=1, column=col).value)
    name = vws.cell(row=3, column=col).value

    if name is None:
        continue

    name = str(name).strip()
    if same_value(flag, target):
        selected.append(name)

for i in range(2):
    cell = ws.cell(row=13 + i, column=1)
    if i < len(selected):
        cell.value = selected[i]
    else:
        cell.value = None

print("target:", target)
print("selected:", selected)

wb.save(OUT)
